<?php
declare(strict_types=1);
function e(?string $v): string { return htmlspecialchars((string)$v, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function csrf_token(): string { if (empty($_SESSION['_csrf'])) $_SESSION['_csrf']=bin2hex(random_bytes(32)); return $_SESSION['_csrf']; }
function csrf_check(): void { if ($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['_csrf']??'', (string)($_POST['_csrf']??''))) { http_response_code(419); exit('Your session expired. Please go back and try again.'); } }
function setting(PDO $db,string $key,string $default=''): string { static $cache=[]; if(array_key_exists($key,$cache)) return $cache[$key]; $q=$db->prepare('SELECT setting_value FROM settings WHERE setting_key=?'); $q->execute([$key]); return $cache[$key]=(string)($q->fetchColumn() ?: $default); }
function money(float $amount): string { return 'Rp '.number_format($amount,0,',','.'); }
function redirect(string $to): never { header('Location: '.$to); exit; }
function flash(string $message,string $type='success'): void { $_SESSION['_flash']=['message'=>$message,'type'=>$type]; }
function get_flash(): ?array { $f=$_SESSION['_flash']??null; unset($_SESSION['_flash']); return $f; }
function admin_required(): void { if(empty($_SESSION['admin_id'])) redirect('login.php'); }
function cart_count(): int { return array_sum(array_map('intval',$_SESSION['cart']??[])); }
function product_image(?string $path): string { return $path ? 'uploads/products/'.rawurlencode(basename($path)) : 'assets/images/placeholder.svg'; }
function site_header(PDO $db,string $title=''): void { $brand=setting($db,'store_name','KELOMPOK 6'); $announcement=setting($db,'announcement','CURATED FOR YOUR LIFESTYLE.'); ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($title ? $title.' — '.$brand : $brand)?></title><meta name="description" content="<?=e(setting($db,'store_description','Curated for your lifestyle.'))?>"><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="announcement"><?=e($announcement)?></div><header class="site-header"><a class="wordmark" href="index.php"><?=e($brand)?><small>CURATED FOR YOUR LIFESTYLE.</small></a><button class="menu-toggle" aria-label="Menu" onclick="document.querySelector('.nav-links').classList.toggle('open')">☰</button><nav class="nav-links"><a href="index.php">HOME</a><a href="shop.php">SHOP</a><a href="shop.php?featured=1">COLLECTION</a><a href="about.php">ABOUT</a><a href="contact.php">CONTACT</a></nav><div class="header-actions"><a href="shop.php" aria-label="Search">⌕</a><a href="cart.php" aria-label="Shopping bag">BAG <span class="count"><?=cart_count()?></span></a></div></header><main>
<?php }
function site_footer(PDO $db): void { ?><footer class="site-footer"><div><a class="wordmark" href="index.php"><?=e(setting($db,'store_name','KELOMPOK 6'))?></a><p><?=e(setting($db,'footer_text','Thoughtfully selected pieces for everyday living.'))?></p></div><div><b>EXPLORE</b><a href="shop.php">Shop all</a><a href="about.php">Our story</a><a href="contact.php">Contact</a></div><div><b>INFORMATION</b><a href="privacy.php">Privacy policy</a><a href="terms.php">Terms & conditions</a><a href="mailto:<?=e(setting($db,'store_email','hello@example.com'))?>">Customer care</a></div><div><b>CONNECT</b><a href="<?=e(setting($db,'instagram','#'))?>">Instagram</a><a href="<?=e(setting($db,'tiktok','#'))?>">TikTok</a><span><?=e(setting($db,'store_whatsapp',''))?></span></div><div class="copyright">© <?=date('Y')?> <?=e(setting($db,'store_name','KELOMPOK 6'))?>. All rights reserved.</div></footer><script src="assets/js/app.js" defer></script></main></body></html><?php }
function upload_image(array $file,string $folder='products'): ?string { if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null; if(($file['error']??1)!==UPLOAD_ERR_OK || ($file['size']??0)>5*1024*1024) throw new RuntimeException('Image upload failed or file exceeds 5 MB.'); $finfo=new finfo(FILEINFO_MIME_TYPE); $mime=$finfo->file($file['tmp_name']); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if(!isset($allowed[$mime])) throw new RuntimeException('Only JPG, PNG, and WEBP images are accepted.'); $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; $dir=__DIR__.'/../uploads/'.$folder; if(!is_dir($dir) && !mkdir($dir,0755,true)) throw new RuntimeException('Upload directory is unavailable.'); if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name)) throw new RuntimeException('Could not save uploaded image.'); return $name; }
